$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$root='C:\JudasValidation';$base='http://192.168.122.1:8872';$receipts="$root\Receipts\M77"
function Upload($p){Invoke-WebRequest -UseBasicParsing "$base/$([IO.Path]::GetFileName($p))" -Method Post -InFile $p|Out-Null}
try{
 Copy-Item "$receipts\m77-windows-build.log" "$receipts\m77-windows-interrupted-build.log";Upload "$receipts\m77-windows-interrupted-build.log"
 Get-WinEvent -FilterHashtable @{LogName='System';StartTime=(Get-Date).AddHours(-1);Id=1074,6005,6006} -ErrorAction SilentlyContinue|Select-Object -First 5 TimeCreated,Id,Message|ConvertTo-Json -Depth 5|Set-Content "$receipts\m77-windows-os-restart.json" -Encoding UTF8;Upload "$receipts\m77-windows-os-restart.json"
 Invoke-WebRequest -UseBasicParsing "$base/m77-delta.json" -OutFile "$root\m77-delta.json";Invoke-WebRequest -UseBasicParsing "$base/m77-delta.zip" -OutFile "$root\m77-delta.zip"
 Add-Type -AssemblyName System.IO.Compression.FileSystem;$archive=[IO.Compression.ZipFile]::OpenRead("$root\m77-delta.zip");$changed=Get-Content "$root\m77-delta.json" -Raw|ConvertFrom-Json
 try{foreach($file in $changed.files){$dest=Join-Path "$root\Source" $file.path;New-Item -ItemType Directory -Force ([IO.Path]::GetDirectoryName($dest))|Out-Null;[IO.Compression.ZipFileExtensions]::ExtractToFile($archive.GetEntry($file.path),$dest,$true);if((Get-FileHash $dest).Hash.ToLower() -ne $file.sha256){throw "delta mismatch $($file.path)"}}}finally{$archive.Dispose()}
 Invoke-WebRequest -UseBasicParsing "$base/m77-source-final.json" -OutFile "$root\m77-source-final.json";$expected=Get-Content "$root\m77-source-final.json" -Raw|ConvertFrom-Json;foreach($file in $expected.files){if((Get-FileHash (Join-Path "$root\Source" $file.path)).Hash.ToLower() -ne $file.sha256){throw "final source mismatch $($file.path)"}}
 @{verifiedFiles=$expected.files.Count;deltaFiles=$changed.files.Count;freeBytes=(Get-PSDrive C).Free}|ConvertTo-Json|Set-Content "$receipts\m77-windows-final-source-proof.json" -Encoding UTF8;Upload "$receipts\m77-windows-final-source-proof.json";Remove-Item "$root\m77-delta.zip"
 Import-Module "$root\VS2022\Common7\Tools\Microsoft.VisualStudio.DevShell.dll";Enter-VsDevShell -VsInstallPath "$root\VS2022" -SkipAutomaticLocation -DevCmdArguments '-arch=x64 -host_arch=x64';$env:PATH="$root\Git\cmd;$root\VS2022\Common7\IDE\CommonExtensions\Microsoft\CMake\CMake\bin;$env:PATH";$ErrorActionPreference='Continue'
 & cmake --build "$root\Build" --config Release --target judas judas_editor judas_export judas_physical_balance_foundation_tests judas_physical_balance_controller_tests judas_balance_lab_tests judas_physical_animation_tests judas_character_motor_tests --parallel 2 2>&1|Tee-Object "$receipts\m77-windows-build-followup.log";$code=$LASTEXITCODE;Upload "$receipts\m77-windows-build-followup.log";if($code){throw "build $code"}
 @{exitcode=$code;freeBytes=(Get-PSDrive C).Free}|ConvertTo-Json|Set-Content "$receipts\m77-windows-build-summary.json" -Encoding UTF8;Upload "$receipts\m77-windows-build-summary.json";exit 0
}catch{$_|Out-String|Set-Content "$receipts\m77-windows-followup-failure.log" -Encoding UTF8;Upload "$receipts\m77-windows-followup-failure.log";exit 1}
